schema_ddl:
CREATE TABLE dipartimenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome_dipartimento TEXT NOT NULL UNIQUE
);

CREATE TABLE dipendenti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    dipartimento_id INT NOT NULL REFERENCES dipartimenti(id),
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    data_assunzione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE assegnazioni_accessorie_personale (
    id INT GENERATED BY DEFAULT AS IDENTITY,
    dipendente_id INT NOT NULL REFERENCES dipendenti(id) ON DELETE CASCADE,
    nome_benefit TEXT NOT NULL,
    valore_mensile NUMERIC(10, 2) NOT NULL CHECK (valore_mensile >= 0),
    PRIMARY KEY (id, dipendente_id)
);
